from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M10','Previsione e progetto statistico','Modelli temporali, valutazione e argomentazione scientifica')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M10',i,b)
m.sezione_nuova('Il compito previsionale')
p('Origine, orizzonte e informazione disponibile',
'''Una previsione riguarda una variabile futura, definita nelle sue unità e nella sua risoluzione temporale, a partire da informazioni disponibili in un istante preciso. L’origine T identifica l’ultimo tempo utilizzabile, mentre h indica quanti passi separino tale origine dal valore da prevedere. Il risultato può essere una media condizionata, un quantile o un’intera distribuzione. La scelta dipende dall’uso previsto e dalla funzione di perdita, attraverso la quale vengono valutate le conseguenze degli errori.''',formula=r'\widehat y_{T+h\mid T}=E[Y_{T+h}\mid\mathcal F_T]',tikz=d('D01',a(.4,3,7.1,3)+rect(.5,1.6,3.7,2.6)+n(2.1,2.1,'Informazione disponibile',w=2.9,size=10.8)+r'\draw[Quantum,dashed] (4,.9)--(4,4.7);'+n(4,5.1,r'$T$')+n(6.4,5.1,r'$T+h$')+a(4.1,3.8,6.4,3.8,'Quantum')+n(5.4,4.4,'orizzonte h',size=11)+n(3.7,5.9,'Il futuro resta escluso dalla stima.',w=6.8,size=11)),richiamo='L’origine stabilisce quale informazione possa entrare nel procedimento.',origine='M10:1–11')
p('Un test storico con protocollo prefissato',
'''Il laboratorio usa le medie mensili derivate dall’archivio storico di CO₂, riservando gennaio 1985–dicembre 1998 all’addestramento e gennaio 1999–dicembre 2001 alla valutazione. Dalla stessa origine vengono prodotti trentasei valori futuri, senza aggiornare il modello durante il test. Il confronto comprende riferimenti semplici e un SARIMA specificato in anticipo. Le medie mensili mantengono la definizione locale descritta nel modulo precedente, mentre il periodo finale viene aperto soltanto dopo avere fissato la procedura.''',formula=r'n_{\rm train}=168,\qquad h=1,\ldots,36',tikz=d('D02',rect(.5,1.2,5.1,3)+n(2.8,2.1,r'1985–1998\par168 mesi',w=4.1)+rect(5.2,1.2,7,3,'Quantum',15)+n(6.1,2.1,r'1999–2001\par36 mesi',w=1.6,size=10.6)+n(2.8,3.7,'Addestramento',w=4)+n(6.1,3.7,'Test',w=1.6)+n(3.7,5.2,'Origine unica: dicembre 1998.',w=6.8)),richiamo='La valutazione è riferita a un archivio storico e a un compito temporale definito.',origine='M10:4,12–15,27–28')
p('Previsione puntuale e distribuzione condizionata',
'''Con perdita quadratica, la previsione ottimale è la media condizionata, mentre con perdita assoluta è una mediana condizionata. Un intervallo descrive invece una regione della distribuzione futura, la cui ampiezza dipende dal modello e dall’orizzonte. La capacità di prevedere mediante regolarità osservate non identifica da sola un meccanismo causale. Eventi esterni o cambiamenti del processo possono modificare il futuro senza essere rappresentati dalla storia utilizzata per la stima.''',formula=r'\arg\min_a E[(Y-a)^2\mid\mathcal F_T]=E[Y\mid\mathcal F_T]\\ \arg\min_a E[|Y-a|\mid\mathcal F_T]=\operatorname{Med}(Y\mid\mathcal F_T)',destra='La distribuzione predittiva dovrebbe essere valutata rispetto all’impiego: una soglia operativa può richiedere una probabilità di superamento, mentre la pianificazione può dipendere da un quantile alto. La media conserva soltanto una sintesi di tale distribuzione.',richiamo='La quantità prevista e la metrica di valutazione devono essere coerenti.',origine='M10:7–11')

m.sezione_nuova('Riferimenti e valutazione temporale')
p('Ultimo valore, stagione e deriva',
'''Un riferimento semplice stabilisce la prestazione che un modello più articolato dovrebbe migliorare nel compito prescelto. La previsione dell’ultimo valore mantiene costante il livello finale; quella stagionale ripete l’ultimo ciclo disponibile. La deriva estende invece il cambiamento medio per passo fra inizio e fine dell’addestramento, rendendo la previsione sensibile a entrambi gli estremi. La media storica è un riferimento per livelli stabili, ipotesi poco adeguata alla CO₂ crescente.''',formula=r'\widehat y^{\rm ultimo}_{T+h\mid T}=y_T\\ \widehat y^{\rm deriva}_{T+h\mid T}=y_T+h\frac{y_T-y_1}{T-1}',figura='M10/F02',didascalia='Quattro previsioni prodotte dalla stessa origine. La curva grigia conserva i valori osservati nel periodo di test.',richiamo='I riferimenti devono rispettare la stessa informazione e lo stesso orizzonte dei modelli confrontati.',origine='M10:16–25')
c=estratto('M10','riferimenti',"d <- read.csv('dati/co2_1985_2001.csv')\ntr <- d$co2_ppm[1:168]; h <- 36\nultimo <- rep(tail(tr,1),h)\nstagionale <- rep(tail(tr,12),length.out=h)\nderiva <- (tail(tr,1)-head(tr,1))/(length(tr)-1)\ncon_deriva <- tail(tr,1)+(1:h)*deriva\nhead(data.frame(ultimo,stagionale,con_deriva))")
p('Il ciclo stagionale viene ripetuto dal passato',
'''Per gennaio 1999, il riferimento stagionale usa gennaio 1998; per gennaio 2000 e gennaio 2001 riutilizza lo stesso valore, poiché l’origine rimane dicembre 1998. Aggiornare il riferimento con i valori osservati nel test definirebbe una valutazione diversa, nella quale l’informazione cresce nel tempo. Il codice lavora su vettori numerici dopo avere fissato la partizione: questa scelta evita che operazioni fra oggetti ts con calendari differenti producano allineamenti inattesi degli estremi.''',formula=r'\widehat y^{\rm stag}_{T+h\mid T}=y_{T-11+((h-1)\bmod12)}',codice=c,richiamo='Origine fissa e aggiornamento progressivo generano previsioni diverse anche per lo stesso metodo.',origine='M10:18–25,28–29')
p('Origini successive e finestre di addestramento',
'''Una valutazione a origini successive ripete la stima usando soltanto i dati disponibili a ciascuna origine. Con finestra crescente si conserva l’intera storia, mentre una finestra mobile mantiene un numero fisso di osservazioni recenti. La seconda scelta può adattarsi a cambiamenti del processo, al costo di una minore base informativa. Imputazioni, scale, componenti stagionali e selezione del modello devono essere ricalcolate entro ogni finestra, affinché la procedura simuli la disponibilità futura dei dati.''',tikz=d('D03',n(3.7,.35,'Tre origini crescenti illustrative')+''.join(rect(.5,1.2+i*1.35,3.5+i*.8,2.05+i*1.35)+rect(3.6+i*.8,1.2+i*1.35,4.5+i*.8,2.05+i*1.35,'Quantum',20) for i in range(3))+n(3.7,5.6,'Verde: stima; viola: valori futuri valutati.',w=6.8,size=11)),richiamo='Ogni ripetizione deve comprendere tutte le trasformazioni apprese dai dati.',origine='M10:26–35')
p('Validazione interna e test finale hanno ruoli distinti',
'''Nel laboratorio, tre origini interne all’addestramento confrontano SARIMA e riferimento stagionale sui dodici mesi successivi. Il test 1999–2001 resta escluso da questo confronto. Se si utilizzano gli errori interni per scegliere ordini o trasformazioni, la valutazione finale deve riguardare la procedura così selezionata. La figura rende visibile la variabilità della prestazione fra origini, evitando che un singolo valore medio nasconda periodi nei quali il vantaggio del modello cambia.''',figura='M10/F08',didascalia='Origini interne a dicembre 1994, 1995 e 1996. Ogni previsione usa soltanto il passato dell’origine corrispondente.',richiamo='Un periodo usato per scegliere la procedura entra nel processo di selezione e perde il ruolo di test finale.',origine='M10:29–35')

m.sezione_nuova('Memoria autoregressiva e innovazioni')
p('Previsione ricorsiva di un processo AR(1)',
'''Nel modello AR(1) centrato, con innovazioni a media nulla e indipendenti dal passato, la previsione a un passo moltiplica l’ultimo valore per il coefficiente autoregressivo. Ripetendo il condizionamento si ottiene una potenza del coefficiente per gli orizzonti successivi. Con modulo minore di uno, la previsione converge alla media del processo. La ricorsione sostituisce valori futuri ignoti con le loro previsioni, mentre le innovazioni future restano la fonte dell’errore predittivo.''',formula=r'X_t-\mu=\phi(X_{t-1}-\mu)+\varepsilon_t\\ \widehat X_{T+h\mid T}=\mu+\phi^h(X_T-\mu)',tikz=d('D04',n(3.7,.4,'Esempio: μ = 0, φ = 0,65')+rect(.3,1.5,2.2,3)+n(1.25,2.25,'2,000')+a(2.3,2.25,2.7,2.25)+rect(2.8,1.5,4.7,3)+n(3.75,2.25,'1,300')+a(4.8,2.25,5.2,2.25)+rect(5.3,1.5,7.2,3,'Quantum')+n(6.25,2.25,'0,845')+n(1.25,3.7,'Origine',size=11)+n(3.75,3.7,'h = 1',size=11)+n(6.25,3.7,'h = 2',size=11)+n(3.7,5.3,'Ogni passo moltiplica per lo stesso coefficiente.',w=6.8,size=11)),richiamo='La ricorsione richiede che la dinamica stimata resti pertinente nel periodo futuro.',origine='M10:36–41,43–45')
p('L’incertezza cresce con gli shock futuri',
'''La previsione AR(1) condizionata all’origine lascia fuori le innovazioni che si realizzeranno fra T e T più h. L’errore è quindi una somma di shock con pesi geometrici, dalla quale si ricava la varianza predittiva quando le innovazioni sono incorrelate. Nel caso stazionario la varianza converge alla varianza marginale del processo. La banda assume parametri noti e innovazioni gaussiane di deviazione standard unitaria.''',formula=r'e_{T+h\mid T}=\sum_{j=0}^{h-1}\phi^j\varepsilon_{T+h-j}\\ \operatorname{Var}(e_{T+h\mid T})=\sigma_\varepsilon^2\frac{1-\phi^{2h}}{1-\phi^2}',figura='M10/F09',didascalia='AR(1) con φ = 0,65 e ultimo valore 2. La banda puntuale al 95% usa il modello noto della simulazione.',richiamo='L’errore futuro comprende innovazioni non osservabili all’origine della previsione.',origine='M10:9–10,38–45,82')
p('Ordine autoregressivo e condizione sulle radici',
'''Un AR(p) combina più valori passati, ciascuno con il proprio coefficiente. La stazionarietà richiede che le radici del polinomio autoregressivo siano esterne al cerchio unitario; controllare separatamente che ogni coefficiente abbia modulo inferiore a uno è insufficiente. Per esempio, due coefficienti pari a 0,8 producono una radice entro il cerchio unitario. Aumentare l’ordine amplia la memoria rappresentata e il numero di parametri, richiedendo più informazione e una valutazione temporale della prestazione.''',formula=r'\phi(z)=1-\phi_1z-\cdots-\phi_pz^p\\ \phi(z)=0\ \Rightarrow\ |z|>1\quad\text{per stazionarietà}',tikz=d('D05',r'\draw[Classical] (3.7,3) ellipse (1.6 and 1.83908);'+linea(.7,3,6.7,3)+linea(3.7,.5,3.7,5.5)+r'\fill[Quantum] (6.1,2) circle (2.5pt);\fill[Measure] (4.5,3.6) circle (2.5pt);'+n(6.2,1.3,'|z| > 1',size=11)+n(5.1,4.3,'|z| < 1',size=11)+n(3.7,5.9,'Il cerchio separa le due regioni.',w=6.7,size=11)),richiamo='La condizione riguarda il polinomio complessivo, anziché i singoli coefficienti isolati.',origine='M10:37,41–43')
p('Il modello MA descrive innovazioni ritardate',
'''In un MA(q), il valore corrente combina l’innovazione presente con un numero finito di innovazioni passate. Per q uguale a uno, lo stesso shock contribuisce a due osservazioni consecutive, generando una covarianza al primo ritardo. Ai ritardi maggiori non vi sono innovazioni condivise e l’autocovarianza teorica si annulla. La convenzione di R utilizza il segno più davanti ai coefficienti MA; altre parametrizzazioni possono adottare segni opposti, che devono essere riconosciuti nel confronto dei risultati.''',formula=r'X_t=\mu+\varepsilon_t+\theta\varepsilon_{t-1}\\ \rho(1)=\frac{\theta}{1+\theta^2},\qquad\rho(k)=0\quad(k>1)',tikz=d('D06',n(1.4,1.1,r'$\varepsilon_{t-1}$')+n(5.7,1.1,r'$\varepsilon_t$')+n(1.4,4.3,r'$X_{t-1}$')+n(5.7,4.3,r'$X_t$')+a(1.4,1.8,1.4,3.5)+a(5.7,1.8,5.7,3.5)+a(1.8,1.8,5.2,3.5,'Quantum')+n(4,2.2,r'$\theta$')+n(3.7,5.6,'Un’innovazione è condivisa da due tempi.',w=6.8,size=11)),richiamo='Una media mobile descrittiva combina dati osservati; il modello MA combina innovazioni.',origine='M10:46–50,54–55')
p('Invertibilità e rappresentazione degli shock',
'''L’invertibilità permette di ricostruire stabilmente le innovazioni mediante la storia osservata, sotto la parametrizzazione scelta. Per un MA(1) richiede modulo di theta inferiore a uno; per ordini maggiori si applica la condizione alle radici del polinomio MA. Un modello ARMA combina la memoria dei valori con quella degli shock, mentre la stima ricostruisce innovazioni che non sono direttamente osservate. I residui restituiti dal software sono quindi quantità dipendenti dal modello e dalla sua inizializzazione.''',formula=r'\phi(B)(X_t-\mu)=\theta(B)\varepsilon_t\\ \theta(z)=1+\theta_1z+\cdots+\theta_qz^q',destra='Esercizio: per un MA(1) con θ = 0,5, l’ACF teorica al primo ritardo vale 0,4. Una media centrata di tre osservazioni ha invece una definizione basata su valori prima e dopo t e introduce un uso di informazione futura.',richiamo='L’invertibilità riguarda la rappresentazione delle innovazioni e la confrontabilità delle parametrizzazioni.',origine='M10:51–55')

m.sezione_nuova('Modelli ARIMA e struttura stagionale')
p('ARIMA applica un ARMA alla serie differenziata',
'''La sigla ARIMA(p,d,q) indica l’ordine autoregressivo, il numero di differenze ordinarie e l’ordine della componente MA. L’operatore di differenza cerca una rappresentazione stazionaria sulla quale applicare il modello, mentre una differenziazione superflua può introdurre dipendenza artificiale. La notazione con l’operatore ritardo separa le funzioni dei diversi termini. L’intercetta nella serie differenziata, quando presente, ha un significato diverso dalla media di un processo stazionario nei livelli.''',formula=r'\phi(B)(1-B)^dY_t=c+\theta(B)\varepsilon_t',tikz=d('D07',rect(.4,.8,7,2.1)+n(3.7,1.45,'Serie nei livelli Y',w=6)+a(3.7,2.3,3.7,2.8)+n(3.7,3.3,r'$(1-B)^dY_t$')+a(3.7,3.8,3.7,4.3)+rect(.4,4.5,7,5.8,'Quantum')+n(3.7,5.15,'Dinamica ARMA della serie trasformata',w=6.1,size=11)),richiamo='Gli ordini delle differenze devono derivare da una diagnosi del processo e della scala.',origine='M10:56–58,64–65')
p('Il modello stagionale del laboratorio',
'''Il SARIMA prefissato combina una differenza ordinaria, una differenza a dodici mesi e due componenti MA, una al ritardo uno e una al ritardo stagionale. Il prodotto dei polinomi genera anche un termine al ritardo tredici, il cui coefficiente è il prodotto dei due coefficienti MA. Questa struttura rappresenta dipendenze ordinarie e annuali della serie trasformata. Il modello costituisce un caso didattico da valutare, senza presumere che sia la specificazione migliore per ogni archivio di CO₂.''',formula=r'(1-B)(1-B^{12})Y_t=(1+\theta B)(1+\Theta B^{12})\varepsilon_t\\ =\varepsilon_t+\theta\varepsilon_{t-1}+\Theta\varepsilon_{t-12}+\theta\Theta\varepsilon_{t-13}',destra='La sigla è SARIMA(0,1,1)(0,1,1)[12]. Si forniscono al software i livelli del solo addestramento e gli ordini delle differenze; trasformare prima la serie e specificare nuovamente gli stessi ordini applicherebbe differenze aggiuntive.',richiamo='L’interazione fra i due polinomi produce il ritardo tredici senza introdurre un terzo parametro libero.',origine='M10:59–65')
c=estratto('M10','sarima',"d <- read.csv('dati/co2_1985_2001.csv')\ny <- ts(d$co2_ppm,start=c(1985,1),frequency=12)\ntr <- window(y,end=c(1998,12))\nf <- arima(tr,order=c(0,1,1),\n seasonal=list(order=c(0,1,1),period=12),\n include.mean=FALSE,method='ML')\nstopifnot(f$code==0)\ncoef(f)\nsqrt(diag(f$var.coef))")
p('Specificazione, stima e convergenza',
'''La chiamata specifica il modello e il metodo di massima verosimiglianza, conservando nell’oggetto coefficienti, innovazioni stimate e stato della convergenza. Un codice di convergenza favorevole documenta l’esito numerico dell’ottimizzazione, mentre l’adeguatezza statistica richiede un esame distinto. Criteri informativi e validazione temporale possono confrontare modelli candidati, purché il confronto sia coerente con dati, trasformazioni e verosimiglianze utilizzate. Le scelte compiute osservando il test finale devono essere riconosciute come ulteriori fasi di selezione.''',codice=c,richiamo='Convergenza numerica, adeguatezza del modello e prestazione predittiva sono verifiche complementari.',fonti='R: arima',origine='M10:61–65')

m.sezione_nuova('Diagnostica delle innovazioni stimate')
p('Sequenze residue e cambiamenti di dispersione',
'''Il grafico delle innovazioni stimate permette di riconoscere sequenze persistenti, cambiamenti di variabilità e osservazioni isolate. Nel laboratorio vengono esaminate le posizioni dalla quattordicesima in avanti, rendendo esplicita l’esclusione iniziale associata alle differenze e all’inizializzazione. La presenza di residui prossimi a zero in media può coesistere con dipendenza o dispersione variabile. Prima di aumentare gli ordini si devono verificare calendario, protocolli, trasformazioni ed eventuali forzanti escluse dal modello.''',figura='M10/F04',didascalia='Innovazioni stimate sul solo addestramento, dopo le prime tredici posizioni. Il test finale resta estraneo alla diagnostica del fit.',richiamo='La diagnostica deve collegare le strutture residue a possibili carenze del modello o dei dati.',origine='M10:66–68,72–73')
p('Autocorrelazione residua e ritardi considerati',
'''L’ACF dei residui verifica se rimangano relazioni lineari ai ritardi esaminati. Superamenti isolati delle bande possono emergere per caso, mentre sequenze regolari o ricorrenze stagionali suggeriscono una struttura residua da approfondire. I residui provengono da un modello stimato e le bande puntuali mantengono un valore diagnostico approssimativo. La scelta del massimo ritardo deve essere coerente con frequenza, numerosità e strutture di interesse, evitando di scegliere soltanto una finestra che produca un esito favorevole.''',figura='M10/F05',didascalia='ACF delle innovazioni stimate fino a ventiquattro mesi. Le bande tratteggiate sono riferimenti puntuali approssimativi.',richiamo='L’assenza di un segnale nell’ACF riguarda i ritardi e la dipendenza lineare esaminati.',origine='M10:69–75')
p('Il test di Ljung–Box aggrega più autocorrelazioni',
'''La statistica di Ljung–Box somma le autocorrelazioni residue al quadrato, applicando una correzione dipendente dal ritardo. La calibrazione approssimata tiene conto dei parametri dinamici stimati. Con ventiquattro ritardi e due coefficienti MA, il laboratorio usa ventidue gradi di libertà e ottiene Q circa 14,24, con p circa 0,893. Il risultato non evidenzia autocorrelazione residua secondo questa verifica, lasciando aperte distribuzione, stabilità e prestazione sul futuro.''',formula=r'Q=n(n+2)\sum_{k=1}^{\ell}\frac{\widehat\rho_k^2}{n-k}\\ Q\ \dot\sim\ \chi^2_{\ell-r},\qquad\ell=24,\quad r=2',destra='Il codice usa Box.test sui residui selezionati, con type = "Ljung-Box" e fitdf = 2. Una seconda implementazione calcola esplicitamente la somma e controlla che coincida con la statistica restituita dalla funzione.',richiamo='Un mancato rifiuto non dimostra che il modello rappresenti ogni proprietà del processo.',origine='M10:70–71,74–75')
p('Distribuzione residua e affidabilità delle bande',
'''Il QQ plot confronta i quantili delle innovazioni stimate con quelli di una distribuzione normale. Deviazioni nelle code possono segnalare che un intervallo gaussiano descriva male eventi estremi, anche quando l’ACF risulti rassicurante. La dispersione può inoltre cambiare nel tempo o dipendere da condizioni esterne. L’esame congiunto del grafico temporale e della distribuzione aiuta a distinguere queste possibilità, mantenendo la diagnosi riferita al campione di addestramento e al modello stimato.''',figura='M10/F06',didascalia='QQ plot delle innovazioni stimate. La retta fornisce un riferimento grafico per la forma della distribuzione.',richiamo='Incorrelazione, forma della distribuzione e costanza della dispersione richiedono controlli distinti.',origine='M10:67–75')

m.sezione_nuova('Previsioni, errori e copertura')
p('Intervalli predittivi condizionati al modello stimato',
'''Il metodo predict restituisce previsioni e relativi errori standard, dai quali viene costruita una banda gaussiana puntuale. Per il modello ARIMA di R, tali errori standard escludono l’incertezza nella stima dei coefficienti; anche selezione del modello, discontinuità future e forzanti assenti possono restare fuori dalla banda. La figura confronta osservato e previsto mantenendo visibile l’ampiezza dell’intervallo a ciascun orizzonte. Il livello nominale riguarda una procedura sotto il modello assunto.''',formula=r'I_{T+h}=\widehat y_{T+h\mid T}\pm z_{0,975}\,\widehat{SE}_h',figura='M10/F01',didascalia='Verde: previsione SARIMA; viola: osservato. La fascia indica intervalli gaussiani puntuali al 95%, condizionati al modello stimato.',richiamo='Una banda puntuale al 95% non equivale a una regione simultanea al 95% per l’intera traiettoria.',fonti='R: predict.Arima',origine='M10:76–77,81–83')
c=estratto('M10','previsione',"d <- read.csv('dati/co2_1985_2001.csv')\ntr <- ts(d$co2_ppm[1:168],start=c(1985,1),frequency=12)\nf <- arima(tr,c(0,1,1),seasonal=list(order=c(0,1,1),\n period=12),include.mean=FALSE,method='ML')\np <- predict(f,n.ahead=36)\nmedia <- as.numeric(p$pred); se <- as.numeric(p$se)\nlimiti <- cbind(media-1.96*se,media+1.96*se)\nstopifnot(length(media)==36,all(se>0))")
p('Date, lunghezze e orientamento dell’errore',
'''La previsione deve essere associata alle date future nello stesso ordine dei valori osservati. Prima delle metriche si verificano lunghezze, finitezza e corrispondenza temporale, poiché un disallineamento può produrre errori plausibili ma privi di significato. Nel modulo l’errore è definito come osservato meno previsto: valori positivi indicano sottostima. Gli estremi della banda vengono calcolati sulla stessa previsione e nelle medesime unità della risposta.''',formula=r'e_h=y_{T+h}-\widehat y_{T+h\mid T}',codice=c,richiamo='Le metriche hanno significato soltanto se ogni previsione è confrontata con l’osservazione corretta.',origine='M10:77–80,84–85')
p('MAE e RMSE sul periodo storico riservato',
'''Il confronto usa gli stessi trentasei mesi e la stessa scala in ppm. Il SARIMA ottiene MAE circa 0,974 e RMSE circa 1,062; il riferimento stagionale raggiunge RMSE circa 3,109, mentre quello con deriva arriva a circa 2,148. Questi risultati descrivono il compito a origine fissa nel periodo prescelto. La metrica aggregata combina orizzonti differenti e deve essere affiancata al grafico degli errori, per riconoscere eventuali deterioramenti sistematici lungo la previsione.''',formula=r'MAE=\frac1H\sum_{h=1}^H|e_h|,\qquad RMSE=\sqrt{\frac1H\sum_{h=1}^He_h^2}',figura='M10/F03',didascalia='RMSE calcolato in R sul test 1999–2001. Tutti i metodi usano la stessa origine e gli stessi valori osservati.',richiamo='Un vantaggio su questo periodo deve essere verificato su altre origini prima di generalizzarlo.',origine='M10:32,78–80,83–85')
p('La sequenza degli errori conserva informazione',
'''Una media degli errori o una metrica complessiva può nascondere periodi di sottostima e sovrastima persistenti. La sequenza osservato meno previsto mostra come la prestazione vari lungo i trentasei orizzonti, mantenendo visibile l’orientamento dello scarto. In una valutazione a origine fissa vi è un solo errore per ciascun orizzonte, per cui la sua variabilità non può essere stimata con precisione da questo singolo test. Origini successive consentono confronti più informativi a pari distanza dal futuro.''',figura='M10/F07',didascalia='Errori SARIMA sul test, con segno osservato meno previsto. Ogni mese corrisponde a un orizzonte diverso dalla stessa origine.',richiamo='La prestazione deve essere descritta anche rispetto all’orizzonte e al periodo di applicazione.',origine='M10:9,28–32,78–85')
p('Copertura osservata e ampiezza degli intervalli',
'''Nel test storico tutti i trentasei valori ricadono nei rispettivi intervalli al 95%. La frequenza osservata è quindi uno, ma le osservazioni appartengono a una stessa traiettoria e gli errori ai diversi orizzonti sono dipendenti. Questo risultato non dimostra copertura universale né garantisce che la banda sia adeguatamente informativa. Una valutazione completa confronta copertura e ampiezza su origini ripetute, distinguendo il livello puntuale da un obiettivo simultaneo sull’intero percorso futuro.''',formula=r'\widehat c=\frac1H\sum_{h=1}^H\mathbf1\{y_{T+h}\in I_{T+h}\}=1',tikz=d('D08',n(3.7,.4,'Copertura e precisione della previsione')+linea(.8,2.2,6.6,2.2,'Quantum')+linea(2.4,4,5,4,'Classical')+''.join(linea(x,y-.3,x,y+.3,col) for x,y,col in [(.8,2.2,'Quantum'),(6.6,2.2,'Quantum'),(2.4,4,'Classical'),(5,4,'Classical')])+n(3.7,2.2,r'$\bullet$')+n(3.7,4,r'$\bullet$')+n(3.7,5.4,'Entrambi includono il valore; le ampiezze differiscono.',w=6.7,size=11)),richiamo='La sola copertura può essere elevata anche con intervalli troppo ampi per l’uso previsto.',origine='M10:81–85')

m.sezione_nuova('Sistemi multivariati e contributo predittivo')
p('Un VAR rappresenta la dinamica congiunta',
'''Un modello autoregressivo vettoriale collega ciascuna variabile ai valori passati di tutte le variabili incluse. Nel generatore bivariato del corso, X dipende dal proprio passato con coefficiente 0,5, mentre Y combina 0,35 del proprio passato e 0,6 del passato di X. Il termine inverso da Y a X è nullo per costruzione. La stabilità richiede autovalori della matrice dinamica con modulo inferiore a uno; nel caso illustrato valgono 0,5 e 0,35.''',formula=r'\mathbf Z_t=\mathbf c+A\mathbf Z_{t-1}+\mathbf u_t,\qquad A=\begin{pmatrix}0,5&0\\0,6&0,35\end{pmatrix}',tikz=d('D09',n(1.5,1,r'$X_{t-1}$')+n(5.8,1,r'$Y_{t-1}$')+n(1.5,4.7,r'$X_t$')+n(5.8,4.7,r'$Y_t$')+a(1.5,1.7,1.5,3.9)+a(5.8,1.7,5.8,3.9,'Quantum')+a(2,1.7,5.3,3.9)+n(.8,2.8,'0,5',size=11)+n(6.5,2.8,'0,35',size=11)+n(3.9,2.3,'0,6',size=11)+n(3.7,5.8,'Coefficienti noti del generatore sintetico.',w=6.8,size=11)),richiamo='Coefficienti incrociati, unità e variabili incluse determinano il significato della dinamica.',origine='M10:86–89,93')
p('Propagazione di uno shock nel sistema noto',
'''La risposta a uno shock iniziale dipende dalle potenze della matrice dinamica. Nel generatore, un incremento unitario di X si attenua nel tempo e si trasmette a Y attraverso il coefficiente incrociato; la risposta di Y compare dal passo successivo. La figura illustra la propagazione imposta dalla simulazione, nella quale il significato dello shock è definito dal modello. Nei dati osservativi, interpretare causalmente una risposta richiede ulteriori ipotesi sull’identificazione delle innovazioni e sulle variabili escluse.''',formula=r'\Delta\mathbf Z_{T+h}=A^h\Delta\mathbf Z_T',figura='M10/F10',didascalia='Risposta del generatore a incremento unitario iniziale di X, con incremento iniziale nullo di Y.',richiamo='Una risposta del modello assume un significato fisico soltanto con un’identificazione adeguata degli shock.',origine='M10:88–93')
p('Il confronto di Granger è condizionato al modello',
'''Per valutare se il passato di X aggiunga informazione alla previsione di Y, si confronta un modello con il solo passato di Y con un modello che include anche X ritardato. Nel caso sintetico il coefficiente aggiuntivo stimato è circa 0,595 e il test F delle regressioni annidate è circa 105,7. L’evidenza riguarda il contributo predittivo condizionato ai ritardi e alle variabili specificati; fattori omessi, integrazione e instabilità possono modificare sia il confronto sia la sua interpretazione scientifica.''',formula=r'H_0:a_{21}=0,\qquad F=\frac{(RSS_R-RSS_U)/q}{RSS_U/(n-p_U)}',destra='Il riferimento F richiede condizioni sulle innovazioni e sulla specificazione. Un’associazione ritardata osservata in uno scatterplot non sostituisce il confronto condizionato. Un mancato rifiuto nella direzione inversa lascia inoltre aperta la possibilità di informazione insufficiente.',richiamo='La capacità predittiva aggiuntiva costituisce una proprietà del sistema informativo e del modello considerati.',origine='M10:90–95')
c=estratto('M10','granger',"p <- read.csv('dati/processi_simulati.csv')\nd <- data.frame(y=tail(p$y_VAR,-1),\n yl=head(p$y_VAR,-1),xl=head(p$x_VAR,-1))\nr <- lm(y~yl,d)\nu <- lm(y~yl+xl,d)\ncoef(u)\nanova(r,u)\nstopifnot(nobs(r)==nobs(u))")
p('Regressioni annidate sulle stesse osservazioni',
'''La costruzione delle variabili ritardate deve conservare le coppie temporali e utilizzare le stesse righe nei modelli ristretto e completo. Il codice elimina il primo valore della risposta e l’ultimo dei predittori, così che ogni riga associ il presente al passato immediato. Il confronto della somma quadratica residua quantifica il miglioramento introdotto dal termine aggiuntivo, mentre la penalizzazione per i gradi di libertà evita di interpretare qualsiasi riduzione come evidenza sufficiente.''',codice=c,richiamo='Il confronto annidato richiede risposta, campione e struttura degli errori coerenti fra modelli.',origine='M10:90–95')

m.sezione_nuova('Progetto integrato e riferimenti')
p('Dalla domanda alla relazione riproducibile',
'''Il progetto può sviluppare morfometria, raggruppamento dei campioni o previsione ambientale, mantenendo una struttura argomentativa comune. La domanda identifica quantità, unità e dominio; il dossier conserva dati, dizionario e provenienza; il controllo qualità precede la scelta del metodo. Il risultato principale viene accompagnato da una verifica e da un’analisi di sensibilità pertinente. La conclusione torna alla domanda iniziale, delimitando quali affermazioni siano sostenute dai dati e quali richiedano osservazioni ulteriori.''',tikz=d('D10',rect(.4,.7,3.3,2.3)+n(1.85,1.5,'Domanda e dominio',w=2.5)+rect(4.1,.7,7,2.3,'Quantum')+n(5.55,1.5,'Dati e provenienza',w=2.5)+a(1.85,2.5,2.8,3.5)+a(5.55,2.5,4.6,3.5,'Quantum')+rect(1.3,3.7,6.1,5.4)+n(3.7,4.55,'Metodo, verifica e conclusione',w=4.2)),richiamo='La valutazione del progetto riguarda la coerenza dell’argomentazione e la tracciabilità dei risultati.',origine='M10:96–110')
p('Consegna e criteri di valutazione del progetto',
'''La consegna comprende una relazione, gli script eseguibili, i dati necessari e figure con unità leggibili. La relazione deve distinguere risultati osservati, ipotesi del modello e inferenze sul dominio dichiarato. I criteri considerano definizione della domanda, qualità dei controlli, adeguatezza del metodo, verificabilità del calcolo e interpretazione dei limiti. Un esito incerto può essere scientificamente informativo quando venga motivato attraverso il disegno, la precisione e le alternative compatibili con i dati.''',destra='Morfometria: confronto fra morfotipi con unità individuale esplicita. Clustering: sensibilità a variabili, scale e numero dei gruppi. Serie temporali: origine, orizzonte, riferimento e valutazione cronologica. Ogni percorso deve includere un controllo equivalente o una simulazione con struttura nota.',richiamo='Una conclusione motivata può riconoscere limiti di identificazione o precisione senza forzare una decisione.',origine='M10:97–107')
p('Riferimenti per previsione e implementazione',
'''Forecasting: Principles and Practice di Hyndman e Athanasopoulos sviluppa riferimenti, validazione temporale e modelli ARIMA; Brockwell e Davis, Introduction to Time Series and Forecasting, fornisce il quadro probabilistico dei processi. La documentazione R di arima, predict.Arima e Box.test precisa convenzioni, errori standard e correzioni dei gradi di libertà. Le figure del modulo sono prodotte in R dai dati allegati; tabelle delle metriche, previsioni e controlli algebrici permettono di ricostruire i risultati esposti.''',destra='Il caso storico usa dati distribuiti con statsmodels, la cui provenienza è documentata nei metadati. I risultati numerici riportati in questa revisione sono stati ricalcolati in R. Le simulazioni AR e VAR illustrano proprietà dei generatori esplicitamente dichiarati.',richiamo='Versioni, specificazioni e convenzioni devono accompagnare ogni risultato destinato alla riproduzione.',fonti='FPP3; R; Brockwell–Davis',origine='M10:108–109')
m.salva()
